<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $chalanNos = \App\Models\GenerateChalan::pluck("chalan_no")->unique()->filter()->toArray(); $billItems = \App\Models\GenerateBillItem::whereIn("ch_no", $chalanNos)->with("generateBill")->get(); foreach (\App\Models\GenerateChalan::all() as $chalan) { $item = $billItems->firstWhere("ch_no", $chalan->chalan_no); if ($item && $item->generateBill) { echo $chalan->chalan_no . " => " . $item->generateBill->bill_no . "\n"; } }
